# apply_phase5.ps1 - Red Angus Portal, phase 5 (feeder cattle)
# Writes NEW files, and replaces existing files ONLY if they are still exactly the
# previous (committed) versions (checked by sha256). Never touches git. Nothing is written until
# every embedded file and every existing file has been checked.
# Usage:  powershell -NoProfile -ExecutionPolicy Bypass -File .\apply_phase5.ps1
param([string]$Root = 'F:\raaaa')
$ErrorActionPreference = 'Stop'

function Get-Sha256Hex([byte[]]$bytes) {
    $sha = [System.Security.Cryptography.SHA256]::Create()
    $hash = $sha.ComputeHash($bytes)
    return ([System.BitConverter]::ToString($hash)).Replace('-', '').ToLower()
}

